import { Component, Element, Event, EventEmitter, h, Host, Listen, Prop, Watch } from '@stencil/core';
import { CLOSE_BUTTON_LABEL } from '../../a11y';
import { OverflowType, Wideness } from '../../types';

/**
 * @slot default - default slot for the content of the modal (here is any HTML content allowed)
 */
@Component({
  tag: 'groupui-modal',
  styleUrl: 'modal.scss',
  shadow: true,
})
export class Modal {
  /**
   * size of the modal for breakpoint xs like in groupui-grid
   */
  @Prop({ reflect: true }) readonly xs: Wideness;

  /**
   * size of the modal for breakpoint s like in groupui-grid
   */
  @Prop({ reflect: true }) readonly s: Wideness;

  /**
   * size of the modal for breakpoint m like in groupui-grid
   */
  @Prop({ reflect: true }) readonly m: Wideness;

  /**
   * size of the modal for breakpoint l like in groupui-grid
   */
  @Prop({ reflect: true }) readonly l: Wideness;

  /**
   * size of the modal for breakpoint xl like in groupui-grid
   */
  @Prop({ reflect: true }) readonly xl: Wideness;

  /**
   * size of the modal for breakpoint xxl like in groupui-grid
   */
  @Prop({ reflect: true }) readonly xxl: Wideness;

  /**
   * shows the modal
   */
  @Prop({ reflect: true, mutable: true }) displayed: boolean = false;

  /**
   * shows the close button
   */
  @Prop({ reflect: true }) readonly closeButton: boolean = false;

  /**
   * centers the modal vertically
   */
  @Prop({ reflect: true }) readonly centered: boolean = false;

  /**
   * width of the modal (depends on the padding)
   * maxWidth wins if the maxWidth property is set and below the actual breakpoint width.
   */
  @Prop({ reflect: true }) readonly maxWidth: string;

  /**
   * margin between modal and modal container as css value (e.g.: 10px 20px 10px 20px)
   */
  @Prop({ reflect: true }) readonly margin: string;

  /**
   * padding between modal and content as css value (e.g.: 10px 20px 10px 20px)
   */
  @Prop({ reflect: true }) readonly padding: string;

  /**
   * margin of the close-icon
   */
  @Prop({ reflect: true }) readonly iconMargin: string;

  /**
   * disables closing the modal when clicked on backdrop
   */
  @Prop({ reflect: true }) readonly disableBackdropClose: boolean = false;

  /**
   * disables closing the modal on escape key press
   */
  @Prop({ reflect: true }) readonly disableEscapeClose: boolean = false;

  /**
   * sets the overflow type of the modal
   */
  @Prop({ reflect: true }) readonly overflow: OverflowType = 'auto';

  /**
   * sets a custom accessible text for the close button
   */
  @Prop({ reflect: true, attribute: 'a11y-label-close-button' }) readonly a11yLabelCloseButton: string;

  @Element() host: HTMLElement;

  /**
   * is dispatched when modal is closed
   */
  @Event({ bubbles: false }) groupuiModalClose: EventEmitter<void>;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  private dialogRef: HTMLDialogElement;
  private popoverContentRef: HTMLElement;

  private defaultOverflow = 'visible';

  @Listen('mousedown', { target: 'window' })
  onBackdropClick(event) {
    if (!this.disableBackdropClose) {
      this.handleClickOnBackdrop(event);
    }
  }

  @Listen('keydown', { target: 'window' })
  onEscapeKeyDown(event: KeyboardEvent) {
    if (event.key === 'Escape') {
      if (this.disableEscapeClose) {
        event.preventDefault();
      }
      if (!this.disableEscapeClose && this.displayed) {
        this.handleEscapeKeyDown(event);
      }
    }
  }

  @Watch('displayed')
  onDisplayedChanged() {
    if (this.displayed) {
      this.defaultOverflow = document.querySelector('body').style.overflow || 'visible';
      document.querySelector('body').style.overflow = 'hidden';
      this.dialogRef?.showModal();
      this.handleFocus();
    } else {
      this.dialogRef?.close();
      document.querySelector('body').style.overflow = this.defaultOverflow;
    }
  }

  componentDidRender() {
    this.handleFocus();
  }

  componentDidLoad() {
    this.handleFocus();
    this.groupuiDidLoad.emit();
    this.onDisplayedChanged();
  }

  disconnectedCallback() {
    document.querySelector('body').style.overflow = this.defaultOverflow;
  }

  private handleFocus() {
    const autoFocusElements = this.getAutoFocusElements();

    if (autoFocusElements.length > 0) {
      (autoFocusElements[0] as HTMLElement)?.focus();
      return;
    }

    const focusableContent = this.getFocusableElements();
    if (focusableContent.length > 0) {
      (focusableContent[0] as HTMLElement)?.focus();
      return;
    }

    if (this.closeButton) {
      const iconButton = this.host.shadowRoot.querySelector('groupui-icon-button') as HTMLGroupuiIconButtonElement;
      const button = iconButton?.shadowRoot.querySelector('button');
      button?.focus();
    }
  }

  private getFocusableElements() {
    const childElements = (this.host as Node).childNodes;
    const childElementsArray = Array.from(childElements);
    const notFocusableTags = ['#text', '#comment', 'GROUPUI-TEXT', 'GROUPUI-HEADLINE'];
    return childElementsArray.filter((el) => notFocusableTags.indexOf(el.nodeName) < 0);
  }

  private getAutoFocusElements() {
    return this.host.querySelectorAll('[autofocus]');
  }

  private handleCloseButtonClick = (event) => {
    event.stopPropagation();
    this.displayed = false;
    this.groupuiModalClose.emit();
  };

  private handleKeyUp = (event: KeyboardEvent) => {
    if (event.code === 'Enter' || event.code === 'Space') {
      this.displayed = false;
      this.groupuiModalClose.emit();
    }
  };

  private handleClickOnBackdrop = (event) => {
    const path = event.path || (event.composedPath && event.composedPath());
    if (!path.includes(this.popoverContentRef) && this.displayed) {
      this.displayed = false;
      this.groupuiModalClose.emit();
      event.stopPropagation();
    }
  };

  private handleEscapeKeyDown = (event: KeyboardEvent) => {
    event.stopPropagation();
    this.displayed = false;
    this.groupuiModalClose.emit();
  };

  render() {
    return (
      <Host>
        <dialog
          id="modal"
          popover="manual"
          style={{ padding: this.margin && this.margin, overflow: this.overflow }}
          class={this.centered ? 'centered' : undefined}
          ref={(el) => (this.dialogRef = el)}
        >
          <div
            id="content"
            ref={(el) => (this.popoverContentRef = el)}
            style={{
              maxWidth: this.maxWidth && this.maxWidth,
              marginBlock: this.margin && this.margin,
              padding: this.padding && this.padding,
              overflow: this.overflow,
            }}
          >
            <slot></slot>
            {this.closeButton && (
              <groupui-icon-button
                id="close-button"
                icon="close-16"
                style={{ margin: this.iconMargin && this.iconMargin }}
                onClick={this.handleCloseButtonClick}
                onKeyUp={this.handleKeyUp}
                aria-label={this.a11yLabelCloseButton || CLOSE_BUTTON_LABEL}
              ></groupui-icon-button>
            )}
          </div>
        </dialog>
      </Host>
    );
  }
}
